css:
.d-rg{box-sizing:border-box;width:300px;max-width:100%;height:150px;overflow-x:hidden;overflow-y:auto;border:1px solid var(--line);border-radius:10px;background:var(--bg)}
.d-rg-body{padding:12px}
.d-rg-h{margin:0 0 4px;font-size:15px;color:var(--ink)}
.d-rg-p{margin:0 0 12px;font-size:11px;line-height:1.6;color:var(--muted)}
.d-rg-card{margin:0 0 12px;padding:10px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);box-shadow:inset 0 1px 0 #fff5;animation:d-scroll-range-fade-out cubic-bezier(.2,.75,.25,1) both;animation-timeline:view();animation-range:cover 55% cover 95%}
.d-rg-t{margin:0;font-size:13px;color:var(--ink)}
.d-rg-k{margin:2px 0 0;font-family:var(--font-mono);font-size:11px;color:var(--faint)}
.d-rg:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
@keyframes d-scroll-range-fade-out{from{opacity:1;transform:translateY(0)}to{opacity:.15;transform:translateY(-8px)}}
